import { createIncident } from '@projexlight/sdk-incident';

const incident = await createIncident({
  tenant_id: req.auth.tenant_id,
  incident_type: 'data.export.failed',
  title: 'Nightly export job failed for tenant',
  severity: 'high',
  owner_persona_id: req.auth.sub,
  sla_due_at: new Date(Date.now() + 4 * 3600_000).toISOString(),
});
console.log(incident.incident_id, incident.status); // <uuid> 'open'

import { transitionIncident, isValidTransition, InvalidIncidentTransition } from '@projexlight/sdk-incident';

if (!isValidTransition('open', 'investigating')) throw new Error('blocked');
try {
  const rec = await transitionIncident(tenantId, incidentId, 'investigating');
  console.log(rec?.status); // 'investigating'
} catch (err) {
  if (err instanceof InvalidIncidentTransition) {
    // 409: move not allowed from the current status
  }
}

import { appendEvidence, EVIDENCE_KINDS } from '@projexlight/sdk-incident';

const evidence = await appendEvidence({
  tenant_id: tenantId,
  incident_id: incidentId,
  kind: 'root_cause',
  body: 'Connection pool exhausted by a 30-day setInterval overflow.',
  recorded_by_persona_id: req.auth.sub,
});
console.log(evidence.audit_entry_hash); // hex receipt proving immutability

import { findSlaBreaches, notifySlaBreach } from '@projexlight/sdk-incident';

const breached = await findSlaBreaches(tenantId, { limit: 50 });
for (const incident of breached) {
  await notifySlaBreach(incident);
}
console.log(`${breached.length} incidents past SLA`);
